/* v0.23 R3 category filters. SEO URLs are not autogenerated or added to sitemap. */
(() => {
  'use strict';
  const form=document.getElementById('category-filter-form');if(!form)return;
  const script=document.getElementById('applied-category-facets');
  let applied=[];
  try{applied=JSON.parse(script?.textContent||'[]')}catch(e){}
  for(const filter of applied){const n=filter.indexOf(':');if(n<1)continue;
    const code=filter.slice(0,n),value=filter.slice(n+1);
    const select=[...form.querySelectorAll('[data-facet-select]')].find(x=>x.dataset.facetSelect===code);
    if(select){select.value=value;continue}
    if(value.includes('..')){const [min,max]=value.split('..');
      const from=[...form.querySelectorAll('[data-facet-min]')].find(x=>x.dataset.facetMin===code);
      const to=[...form.querySelectorAll('[data-facet-max]')].find(x=>x.dataset.facetMax===code);
      if(from)from.value=min;if(to)to.value=max;
    }
  }
  form.addEventListener('submit',event=>{
    event.preventDefault();const query=new URLSearchParams();
    for(const el of form.querySelectorAll('[data-facet-select]')){
      if(el.value)query.append('attr',el.dataset.facetSelect+':'+el.value);
    }
    for(const el of form.querySelectorAll('[data-facet-min]')){
      const code=el.dataset.facetMin;
      const max=[...form.querySelectorAll('[data-facet-max]')].find(x=>x.dataset.facetMax===code);
      if(!el.value&&!max?.value)continue;
      const low=el.value||el.placeholder, high=max.value||max.placeholder;
      if(!low||!high||Number(low)>Number(high)){alert('Проверь диапазон: «От» не может быть больше «До».');return;}
      query.append('attr',code+':'+low+'..'+high);
    }
    window.location.assign(form.action+(query.toString()?'?'+query.toString():''));
  });
})();
